namespace UnityEngine {
 public class Object{public bool Destroyed;public virtual string name{get;set;}public static implicit operator bool(Object o){if(o==null||o.Destroyed)return false;var t=o as Transform;if(t!=null&&t.gameObject!=null&&t.gameObject.Destroyed)return false;var c=o as Component;return c==null||c.gameObject==null||!c.gameObject.Destroyed;}public static void Destroy(Object o){if(o==null)return;o.Destroyed=true;var go=o as GameObject;if(go!=null)foreach(var t in go.transform.Children.ToArray())Destroy(t.gameObject);}public static GameObject Instantiate(GameObject source,Transform parent,bool world){var go=new GameObject{name=source.name};go.transform=source.transform is RectTransform?new RectTransform():new Transform();go.transform.parent=parent;go.transform.localScale=source.transform.localScale;go.transform.position=source.transform.position;go.transform.rotation=source.transform.rotation;if(source.transform is RectTransform r&&go.transform is RectTransform q){q.sizeDelta=r.sizeDelta;q.pivot=r.pivot;}foreach(var c in source.Parts.Values){var clone=(Component)Activator.CreateInstance(c.GetType());go.Add(clone);foreach(var p in c.GetType().GetProperties(BindingFlags.Public|BindingFlags.Instance))if(p.CanRead&&p.CanWrite&&p.Name!="name")p.SetValue(clone,p.GetValue(c));}foreach(var t in source.transform.Children)Instantiate(t.gameObject,go.transform,false);return go;}}
 public class GameObject:Object{bool active=true;Transform current;public static int ComponentReads;public GameObject(){transform=new Transform();}public Transform transform{get=>current;set{current=value;value.gameObject=this;}}public bool activeSelf=>active;public bool activeInHierarchy{get=>active&&(transform.parent==null||transform.parent.gameObject==null||transform.parent.gameObject.activeInHierarchy);set=>active=value;}public Dictionary<Type,Component> Parts=new Dictionary<Type,Component>();public T GetComponent<T>() where T:class{ComponentReads++;foreach(var c in Parts.Values)if(c is T t)return t;return null;}public Component GetComponent(Type t){ComponentReads++;foreach(var c in Parts.Values)if(t.IsInstanceOfType(c))return c;return null;}public T[] GetComponentsInChildren<T>(bool include) where T:class{var all=new List<T>();foreach(var c in Parts.Values)if(c is T x)all.Add(x);foreach(var t in transform.Children)all.AddRange(t.gameObject.GetComponentsInChildren<T>(include));return all.ToArray();}public void Add(Component c){c.gameObject=this;Parts[c.GetType()]=c;}public void SetActive(bool b){active=b;}}
 public class Transform:Object{public GameObject gameObject;public override string name{get=>gameObject!=null?gameObject.name:base.name;set{if(gameObject!=null)gameObject.name=value;else base.name=value;}}Transform upParent;public List<Transform> Children=new List<Transform>();public Transform parent{get=>upParent;set{if(upParent!=null)upParent.Children.Remove(this);upParent=value;if(value!=null&&!value.Children.Contains(this))value.Children.Add(this);}}public Transform Parent{get=>parent;set=>parent=value;}public Vector3 position,localScale=Vector3.one;public Quaternion rotation=Quaternion.identity,localRotation=Quaternion.identity;public Vector3 lossyScale{get{var p=parent==null?Vector3.one:parent.lossyScale;return new Vector3(p.x*localScale.x,p.y*localScale.y,p.z*localScale.z);}}public Vector3 right=>rotation*new Vector3(1,0,0);public Transform Find(string path){Transform current=this;foreach(var name in path.Split('/')){current=current.Children.Find(c=>c.name==name);if(current==null)return null;}return current;}}
 public class RectTransform:Transform{public Vector2 anchorMin,anchorMax,pivot,anchoredPosition,offsetMin,offsetMax;public Vector2 sizeDelta=new Vector2(200,20);public Rect rect=>new Rect(0,0,sizeDelta.x,sizeDelta.y);}
 public struct Rect{public float x,y,width,height;public Rect(float a,float b,float c,float d){x=a;y=b;width=c;height=d;}}
