 public struct Vector3{public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}public static Vector3 zero=>new Vector3();public static Vector3 one=>new Vector3(1,1,1);public static Vector3 up=>new Vector3(0,1,0);public static Vector3 operator +(Vector3 a,Vector3 b)=>new Vector3(a.x+b.x,a.y+b.y,a.z+b.z);public static Vector3 operator *(Vector3 a,float b)=>new Vector3(a.x*b,a.y*b,a.z*b);public static float Distance(Vector3 a,Vector3 b)=>(float)Math.Sqrt((a.x-b.x)*(a.x-b.x)+(a.y-b.y)*(a.y-b.y)+(a.z-b.z)*(a.z-b.z));}
 public struct Quaternion{public float x,y,z,w;public static Quaternion identity=>new Quaternion{w=1};public static Vector3 operator *(Quaternion q,Vector3 v){return new Vector3((1-2*(q.y*q.y+q.z*q.z))*v.x+2*(q.x*q.y-q.z*q.w)*v.y+2*(q.x*q.z+q.y*q.w)*v.z,2*(q.x*q.y+q.z*q.w)*v.x+(1-2*(q.x*q.x+q.z*q.z))*v.y+2*(q.y*q.z-q.x*q.w)*v.z,2*(q.x*q.z-q.y*q.w)*v.x+2*(q.y*q.z+q.x*q.w)*v.y+(1-2*(q.x*q.x+q.y*q.y))*v.z);}}
 public static class Mathf{public const float Deg2Rad=(float)Math.PI/180;public static float Sin(float x)=>(float)Math.Sin(x);public static float Cos(float x)=>(float)Math.Cos(x);public static float Abs(float x)=>Math.Abs(x);public static float Max(float a,float b)=>Math.Max(a,b);}
