public class StatusEffect:UnityEngine.Object{public float m_ttl,m_time;public Character m_character;public int Hash,VisualTriggers;public EffectList m_startEffects=new EffectList();public UnityEngine.GameObject[] m_startEffectInstances;[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]public virtual void ResetTime(){m_time=0;}public virtual void SetLevel(int itemLevel,float skillLevel){}public int NameHash()=>Hash;public float GetDuration()=>m_time;protected void TriggerStartEffects(){VisualTriggers++;var go=new UnityEngine.GameObject();go.Add(new ZNetView{Zdo=new ZDO{m_uid=new ZDOID{Value=1000+VisualTriggers}}});go.transform.position=m_character.transform.position;m_startEffectInstances=new[]{go};}}public class SE_Shield:StatusEffect{public float m_totalAbsorbDamage,m_damage,m_absorbDamage=200,m_absorbDamagePerSkillLevel=5;public int m_ttlPerItemLevel=60;[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]public override void SetLevel(int itemLevel,float skillLevel){if(m_ttlPerItemLevel>0)m_ttl=m_ttlPerItemLevel*itemLevel;m_totalAbsorbDamage=m_absorbDamage+m_absorbDamagePerSkillLevel*skillLevel;}}
public class SEMan{public Character m_character;public List<StatusEffect> Effects=new List<StatusEffect>();public List<StatusEffect> GetStatusEffects()=>Effects;public StatusEffect GetStatusEffect(int h)=>Effects.Find(x=>x.Hash==h);public bool RemoveStatusEffect(StatusEffect s,bool quiet)=>Effects.Remove(s);[System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]public StatusEffect AddStatusEffect(int nameHash,bool resetTime=false,int itemLevel=0,float skillLevel=0,short variant=-1){return Internal_AddStatusEffect(nameHash,resetTime,itemLevel,skillLevel,variant);}
 [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]private StatusEffect Internal_AddStatusEffect(int nameHash,bool resetTime,int itemLevel,float skillLevel,short variant){var existing=GetStatusEffect(nameHash);if(existing){if(resetTime){existing.ResetTime();existing.SetLevel(itemLevel,skillLevel);}return null;}var template=ObjectDB.instance.GetStatusEffect(nameHash);return template?AddStatusEffect(template,false,itemLevel,skillLevel,variant):null;}
 [System.Runtime.CompilerServices.MethodImpl(System.Runtime.CompilerServices.MethodImplOptions.NoInlining)]public StatusEffect AddStatusEffect(StatusEffect statusEffect,bool resetTime=false,int itemLevel=0,float skillLevel=0,short variant=-1){var existing=GetStatusEffect(statusEffect.NameHash());if(existing){if(resetTime){existing.ResetTime();existing.SetLevel(itemLevel,skillLevel);}return null;}var t=(SE_Shield)statusEffect;var x=new SE_Shield{Hash=t.Hash,m_ttl=t.m_ttl,m_character=m_character,m_absorbDamage=t.m_absorbDamage,m_absorbDamagePerSkillLevel=t.m_absorbDamagePerSkillLevel,m_ttlPerItemLevel=t.m_ttlPerItemLevel};Effects.Add(x);x.SetLevel(itemLevel,skillLevel);return x;}}
